 function sameDate(dateStr1, dateStr2) {
 var d1 = new Date(dateStr1);
 var d2 = new Date(dateStr2);

 return d1.getDate() === d2.getDate() &&
 d1.getMonth() === d2.getMonth() &&
 d1.getFullYear() === d2.getFullYear();
 }


for(var i =0 ; i<tw.local.transactions.listLength;i++){

	
	//for new added transactions, remove the added amount
	if(tw.local.transactions[i].changeOperation == "N"){
				
		tw.local.transactions[i].existAmount = tw.local.transactions[i].existAmount - tw.local.transactions[i].amountAllocatedForCurrencyRequest;

	}
	
	//changed or deleted transactions
	else{

		for (var x = 0; x < tw.local.lastRequestTransactions.length; x++) {
			
			if (tw.local.transactions[i].referenceNumber === tw.local.lastRequestTransactions[x].referenceNumber &&
 		 sameDate(tw.local.transactions[i].postingDate, tw.local.lastRequestTransactions[x].postingDate)){
	 
 			// for changed transactions replace the new added amount with the old amount
 			if(tw.local.transactions[i].changeOperation == "C"){
 			 	
 			 	tw.local.transactions[i].existAmount = tw.local.transactions[i].existAmount - tw.local.transactions[i].allocatedAmountInRequestCurrency + tw.local.lastRequestTransactions[x].allocatedAmountInRequestCurrency;
 			 	break;	
 			 }
 			 
 			//for deleted transactions add again the deleted amount
 			else{
 				tw.local.transactions[i].existAmount = tw.local.transactions[i].existAmount + tw.local.lastRequestTransactions[x].allocatedAmountInRequestCurrency;
 				break;
 			}
 		 }
	
		}
	}
}
	


"]}},{"itemSubjectRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","name":"errorMessage","isCollection":false,"declaredType":"dataObject","id":"2056.2d291672-19d5-48c1-8982-09071c246253"},{"targetRef":"39672ed5-d216-4a3a-b967-0f0c41221716","extensionElements":{"sequenceFlowImplementation":[{"fireValidation":"Never","sboSyncEnabled":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TSequenceFlowImplementation"}],"endStateId":["guid:f6ffc3b64be5dfa5:4157166b:18ab80e0606:-6f83"],"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"bottomCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":true,"showLabel":false}]},"name":"To End","declaredType":"sequenceFlow","id":"38ebb3e5-5eef-495d-95a7-6c376627cec3","sourceRef":"28308fa1-5110-41a6-be4f-5a5bb990320f"},{"startQuantity":1,"outgoing":["4d6c50eb-f16b-4426-90a6-24f7f159eca3"],"incoming":["4936d0b8-a9de-4262-8fb1-d89341656c22"],"extensionElements":{"postAssignmentScript":["
