:{"linkVisualInfo":[{"sourcePortLocation":"bottomCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Exception Handling","declaredType":"sequenceFlow","id":"1c11a2ef-4389-4716-b431-86568769a3c3","sourceRef":"e7ceeed4-ca0c-4ecf-8fdf-6763a88cd060"},{"itemSubjectRef":"itm.12.3fa0d7a0-828a-4d60-99cc-db5ed143fc2d","name":"latestID","isCollection":false,"declaredType":"dataObject","id":"2056.8595ef13-6013-431d-b9ad-c83807495b62"},{"startQuantity":1,"outgoing":["11565db6-462b-446b-8c5f-9976a33d5812"],"incoming":["fc588397-1809-4dcd-a3ba-4d616f009052"],"extensionElements":{"nodeVisualInfo":[{"width":95,"x":205,"y":69,"declaredType":"TNodeVisualInfo","height":70}],"preAssignmentScript":[]},"name":"Check changed transactions","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"1f5b76bc-43fe-4309-88c3-55c8a86496a6","scriptFormat":"text/x-javascript","script":{"content":["//----------------------------------------------------------
 function sameDate(dateStr1, dateStr2) {
 var d1 = new Date(dateStr1);
 var d2 = new Date(dateStr2);

 return d1.getDate() === d2.getDate() &&
 d1.getMonth() === d2.getMonth() &&
 d1.getFullYear() === d2.getFullYear();
 }
//compare lists
function compareLists(oldList, newList) {

 // Check for added and changed items
 for (var i = 0; i < newList.length; i++) {
 var found = false;
 var isChanged = false;

 for (var j = 0; j < oldList.length; j++) {
 if (newList[i].referenceNumber === oldList[j].referenceNumber &&
 sameDate(newList[i].postingDate, oldList[j].postingDate)) {
 
 found = true;

 if (newList[i].existAmount !== oldList[j].existAmount) {
 isChanged = true;
 }

 break;
 }
 }

 if (!found) {
	// new added item
 	newList[i].changeOperation = "N";
 }

 if (isChanged) {
 	//changed item
 	newList[i].changeOperation = "C";
 }
 }

 // Check for deleted items
 for (var i = 0; i < oldList.length; i++) {
 var found = false;

 for (var j = 0; j < newList.length; j++) {
 if (oldList[i].referenceNumber === newList[j].referenceNumber &&
 sameDate(oldList[i].postingDate, newList[j].postingDate)) {
 found = true;
 break;
 }
 }

 if (!found) {
 	newList.insertIntoList(newList[newList.listLength], oldList[i]);
	newList[newList.listLength-1].changeOperation = "D";
 }
 }

 return newList


}

tw.local.transactions = compareLists(tw.local.lastRequestTransactions , tw.local.transactions);

//-----LOGGING____________

for(var i =0 ; i<tw.local.transactions.listLength;i++){

	log.info("OPERTAION["+i+"] : "+tw.local.transactions[i].changeOperation);

}"]}},{"targetRef":"33f719c2-4053-4707-abe2-6e6659c07fb0","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"topCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Get Transactions IDs","declaredType":"sequenceFlow","id":"11565db6-462b-446b-8c5f-9976a33d5812","sourceRef":"1f5b76bc-43fe-4309-88c3-55c8a86496a6"},{"extensionElements":{"defaultValue":[{"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TDefaultValue","useDefault":false,"value":"var autoObject = new tw.object.listOf.toolkit.TWSYS.Integer();
