processPrePosts.script:
if(!!tw.local.LockedErrorMSG)
	tw.local.isSuccessful = false;
else
	tw.local.isSuccessful = true;

TWComponent.script:
//----------------------------------------------------------
  function sameDate(dateStr1, dateStr2) {
    var d1 = new Date(dateStr1);
    var d2 = new Date(dateStr2);

    return d1.getDate() === d2.getDate() &&
           d1.getMonth() === d2.getMonth() &&
           d1.getFullYear() === d2.getFullYear();
  }


for(var i =0 ; i<tw.local.transactions.listLength;i++){

	
	//for new added transactions, remove the added amount
	if(tw.local.transactions[i].changeOperation == "N"){
				
		tw.local.transactions[i].existAmount = tw.local.transactions[i].existAmount - tw.local.transactions[i].amountAllocatedForCurrencyRequest;

	}
	
	//changed or deleted transactions
	else{

		for (var x = 0; x < tw.local.lastRequestTransactions.length; x++) {
			
			if (tw.local.transactions[i].referenceNumber === tw.local.lastRequestTransactions[x].referenceNumber &&
        		    sameDate(tw.local.transactions[i].postingDate, tw.local.lastRequestTransactions[x].postingDate)){
	 
        			// for changed transactions replace the new added amount with the old amount
        			if(tw.local.transactions[i].changeOperation == "C"){
        			  	
        			  	tw.local.transactions[i].existAmount =  tw.local.transactions[i].existAmount - tw.local.transactions[i].allocatedAmountInRequestCurrency +  tw.local.lastRequestTransactions[x].allocatedAmountInRequestCurrency;
        			  	break;	
        			  }
        			  
        			//for deleted transactions add again the deleted amount
        			else{
        				tw.local.transactions[i].existAmount = tw.local.transactions[i].existAmount + tw.local.lastRequestTransactions[x].allocatedAmountInRequestCurrency;
        				break;
        			}
        		 }
	
		}
	}
}

processPrePosts.script:
if(tw.local.results[0].rows.listLength > 0){
	    var maxReversedID = tw.local.results[0].rows[0].data[0];

	for(var i =0; i<tw.local.results[0].rows.listLength;i++){
	
		var currentID = tw.local.results[0].rows[i].data[0];

		tw.local.reversedIDs.insertIntoList(tw.local.reversedIDs.listLength, currentID);
		if (currentID > maxReversedID) 
           		 maxReversedID = currentID;
        
	
	}
	  tw.local.latestID = maxReversedID;

}

function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.sqlStat = new tw.object.SQLStatement();
tw.local.sqlStat.sql = "SELECT ID FROM "+tw.env.DBSchema+".ODC_REQUESTINFO WHERE PARENTREQUESTNO= ?";

tw.local.sqlStat.parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStat.parameters.insertIntoList(tw.local.sqlStat.parameters.listLength, addSQLParameter(tw.local.parentRequestNo));

TWComponent.script:
//----------------------------------------------------------
  function sameDate(dateStr1, dateStr2) {
    var d1 = new Date(dateStr1);
    var d2 = new Date(dateStr2);

    return d1.getDate() === d2.getDate() &&
           d1.getMonth() === d2.getMonth() &&
           d1.getFullYear() === d2.getFullYear();
  }
//compare lists
function compareLists(oldList, newList) {

  // Check for added and changed items
  for (var i = 0; i < newList.length; i++) {
    var found = false;
    var isChanged = false;

    for (var j = 0; j < oldList.length; j++) {
      if (newList[i].referenceNumber === oldList[j].referenceNumber &&
          sameDate(newList[i].postingDate, oldList[j].postingDate)) {
        
        found = true;

        if (newList[i].existAmount !== oldList[j].existAmount) {
          isChanged = true;
        }

        break;
      }
    }

    if (!found) {
	// new added item
    	newList[i].changeOperation = "N";
    }

    if (isChanged) {
    	//changed item
    	newList[i].changeOperation = "C";
    }
  }

  // Check for deleted items
  for (var i = 0; i < oldList.length; i++) {
    var found = false;

    for (var j = 0; j < newList.length; j++) {
      if (oldList[i].referenceNumber === newList[j].referenceNumber &&
          sameDate(oldList[i].postingDate, newList[j].postingDate)) {
        found = true;
        break;
      }
    }

    if (!found) {
    	newList.insertIntoList(newList[newList.listLength], oldList[i]);
	newList[newList.listLength-1].changeOperation = "D";
    }
  }

  return newList


}

tw.local.transactions = compareLists(tw.local.lastRequestTransactions , tw.local.transactions);

//-----LOGGING____________

for(var i =0 ; i<tw.local.transactions.listLength;i++){

	log.info("OPERTAION["+i+"] : "+tw.local.transactions[i].changeOperation);

}

processPrePosts.script:
if (tw.local.sqlResult.listLength > 0){

	for(var i = 0;i<tw.local.sqlResult.listLength;i++){
		if(tw.local.sqlResult[i].rows.listLength >0 ){
	   	 	tw.local.transactions[i].amountAllocatedForCurrencyRequest = tw.local.sqlResult[i].rows[0].data[0] || 0;
	   	      tw.local.transactions[i].allocatedAmountInRequestCurrency = tw.local.sqlResult[i].rows[0].data[1] || 0;
	   	     }

	}

		
}

log.info("<<Transactions AFTER>>");
log.info(tw.local.transactions);

//Get "allocated amount in current request" and "amount in request currency" of the latest request worked on the transactions before cancelled request
tw.local.sqlStatement = new tw.object.listOf.SQLStatement();

for (var i = 0; i < tw.local.transactions.listLength; i++) {
    var sqlStatement = new tw.object.SQLStatement();

    sqlStatement.sql =
        "SELECT AMOUNTINCURRENTREQ, AMOUNTINREQCURRENCY " +
        "FROM "+tw.env.DBSchema+".ODC_SELECTEDTRANSACTIONS " +
        "WHERE ID = (SELECT MAX(ID) FROM "+tw.env.DBSchema+".ODC_SELECTEDTRANSACTIONS WHERE REQUESTID <> ? AND isDeleted <> 'Yes' AND TRANSACTIONID = ? " +
        "  GROUP BY TRANSACTIONID );";

    sqlStatement.parameters = new tw.object.listOf.SQLParameter();

    var param1 = new tw.object.SQLParameter();
    param1.value = tw.local.transactions[i].requestID;
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param1);

    var param2 = new tw.object.SQLParameter();
    param2.value = tw.local.transactionsIDs[i]; 
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param2);

    tw.local.sqlStatement.insertIntoList(tw.local.sqlStatement.listLength, sqlStatement);
}

